  var targets = [0.894, 0.816, 0.447];
  var ids = ['gv-tj-0','gv-tj-1','gv-tj-2'];
  var ok = true;
  ids.forEach(function(id,i){
    var v = parseFloat(String(gvEl(id).value||'').replace(',','.'));
    if(isNaN(v) || Math.abs(v-targets[i]) > 0.006) ok = false;
  });
